// Modified by: Etienne Cimon
// Date: 08.05.2017
// Description: Flush controller
//
// hyp8 (group-10 T2, counted drain -- H1): the reference flushed every
// back-end pipeline register with a single-cycle kill and refetched on the
// same cycle. Under the staged microarchitecture a one-cycle flush can miss
// a pipeline register that was captured pre-flush and re-arms later, and a
// fence.i/sfence/satp-change refetch can otherwise run ahead of a stale TLB
// walk or stale I$ response (H1: fetch, decode D1-D3, realign/scan, the TLB
// pipeline T1-T3 and the I$ response stages must all be dead before refetch).
// Every full-flush source (the legs that raise set_pc_commit, plus the
// drain_force kill) therefore now runs a counted drain: the kill outputs are
// held for DRAIN_CYCLES cycles and set_pc_commit_o/mem_replay_pc_o are only
// raised on the last drain cycle. The refetch PC is captured at the trigger
// (pc_commit_i is the live scoreboard head and advances once the head pops).
// The CSR side-effect request arrives registered +1 from csr_write (H14) and
// is consumed as such -- it simply becomes a drain trigger one cycle later.
// Exception/eret/debug flushes keep single-cycle semantics (the frontend
// takes their trap vector on the live ex_valid/eret line, not through
// set_pc_commit) and RELEASE a pending drain: the reference's last-write-wins
// ordering made the exception leg overwrite every other flush output.
// Mispredict and the fine-grain SMT switch stay immediate partial flushes.

module controller
  import g6lc_core_pkg::*;
#(
    parameter config_pkg::g6lc_cfg_t G6LCCfg = config_pkg::g6lc_cfg_empty,
    parameter g6lc_hyp_pkg::g6lc_hyp_cfg_t HypCfg = g6lc_hyp_pkg::Hyp8,
    parameter type bp_resolve_t = logic
) (
    // Subsystem Clock - SUBSYSTEM
    input logic clk_i,
    // Asynchronous reset active low - SUBSYSTEM
    input logic rst_ni,
    // Virtualization mode - CSR_REGFILE
    input logic v_i,
    // Set PC om PC Gen - FRONTEND
    output logic set_pc_commit_o,
    // Flush the IF stage - FRONTEND
    output logic flush_if_o,
    // Flush un-issued instructions of the scoreboard - FRONTEND
    output logic flush_unissued_instr_o,
    // Flush ID stage - ID_STAGE
    output logic flush_id_o,
    // Flush EX stage - EX_STAGE
    output logic flush_ex_o,
    // Flush branch predictors - FRONTEND
    output logic flush_bp_o,
    // Flush ICache - CACHE
    output logic flush_icache_o,
    // Flush DCache - CACHE
    output logic flush_dcache_o,
    // Acknowledge the whole DCache Flush - CACHE
    input logic flush_dcache_ack_i,
    // Flush TLBs - EX_STAGE
    output logic flush_tlb_o,
    // TO_BE_COMPLETED - TO_BE_COMPLETED
    output logic flush_tlb_vvma_o,
    // TO_BE_COMPLETED - TO_BE_COMPLETED
    output logic flush_tlb_gvma_o,
    // Halt request from CSR (WFI instruction) - CSR_REGFILE
    input logic halt_csr_i,
    // Halt request from accelerator dispatcher - ACC_DISPATCHER
    input logic halt_acc_i,
    // Halt frontend during fence.i to prevent fetching stale instructions
    output logic halt_frontend_o,
    // Halt signal to commit stage - COMMIT_STAGE
    output logic halt_o,
    // Return from exception - CSR_REGFILE
    input logic eret_i,
    // We got an exception, flush the pipeline - FRONTEND
    input logic ex_valid_i,
    // set the debug pc from CSR - FRONTEND
    input logic set_debug_pc_i,
    // We got a resolved branch, check if we need to flush the front-end - EX_STAGE
    input bp_resolve_t resolved_branch_i,
    // We got an instruction which altered the CSR, flush the pipeline - CSR_REGFILE
    input logic flush_csr_i,
    // fence.i in - ACC_DISPATCH
    input logic fence_i_i,
    // fence in - ACC_DISPATCH
    input logic fence_i,
    // We got an instruction to flush the TLBs and pipeline - COMMIT_STAGE
    input logic sfence_vma_i,
    // TO_BE_COMPLETED - TO_BE_COMPLETED
    input logic hfence_vvma_i,
    // TO_BE_COMPLETED - TO_BE_COMPLETED
    input logic hfence_gvma_i,
    // Flush request from commit stage - COMMIT_STAGE
    input logic flush_commit_i,
    // Committing entry requests refetch from its own PC - COMMIT_STAGE
    input logic replay_i,
    // flush_commit_i is a memory-order replay: frontend refetches the same PC
    output logic mem_replay_pc_o,
    // Flush request from accelerator - ACC_DISPATCHER
    input logic flush_acc_i,
    // U6.1 coarse-grain SMT switch: full pipeline flush, PC comes from PC bank
    input logic smt_switch_i,
    // N1c bounded drain force - SMT selector (drained handoff): the resident
    // hart's uncommitted state is killed so the pending handoff can complete;
    // the outgoing hart's restart PC is banked via npc_alt, not set_pc.
    input logic drain_force_i,
    // Live scoreboard head PC - COMMIT_STAGE (hyp8: captured at drain trigger
    // because the head pops while the drain holds the kill)
    input logic [G6LCCfg.VLEN-1:0] pc_commit_i,
    // Captured refetch PC, valid while drain_pending_o - FRONTEND (hyp8)
    output logic [G6LCCfg.VLEN-1:0] pc_commit_hold_o,
    // A counted drain is holding the refetch back - FRONTEND/top mux (hyp8)
    output logic drain_pending_o
);

  // active fence - high if we are currently flushing the dcache
  logic fence_active_d, fence_active_q;
  logic flush_dcache;
  // Added fence_i_active state to track fence.i progress
  logic fence_i_active_d, fence_i_active_q;

  // T6b-3 exit: a fine-grain switch must never degrade a commit-level flush.
  // commit_flush enumerates every flush_id_o source in flush_ctrl below the
  // defaults (mispredict / cf-unissued legs raise only flush_unissued_instr_o,
  // so they are deliberately absent). Under mixed residency an eret/exception
  // coincident with a switch still needs the scoreboard+EX kill: already-issued
  // copies of the flushing instruction survive an unissued-only flush and
  // re-commit against a bank context the first commit already mutated (the
  // parked-xret duplicate-mret failure). Under drained handoff or a single
  // hart MixedSmt folds to 0 and the override below is bit-identical.
  localparam bit MixedSmt = G6LCCfg.NrHarts > 1 && !G6LCCfg.SmtDrainedHandoff;
`ifdef G6LC_MUT_CTRL_SWITCH_DEGRADES
  // Review-only mutation: the switch override degrades commit-level flushes
  // again -- a resident peer's already-issued copies survive and re-commit.
  localparam bit SwitchGuardMut = 1'b1;
`else
  localparam bit SwitchGuardMut = 1'b0;
`endif
  logic commit_flush;

  // ---- hyp8 counted drain (H1) -------------------------------------------
  // Deepest in-flight stage count across the flushed domains: decode D1..D3
  // (+2 entry/realign), the rename pipeline, the staggered ALU, the LSQ
  // verdict (3), the D$ hit pipeline (+3 incl. response), the CSR read.
  function automatic int unsigned hyp_max4(input int unsigned a,
                                           input int unsigned b,
                                           input int unsigned c,
                                           input int unsigned d);
    int unsigned m;
    m = (a > b) ? a : b;
    m = (m > c) ? m : c;
    return (m > d) ? m : d;
  endfunction

  localparam int unsigned DRAIN_CYCLES = hyp_max4(
      hyp_max4(HypCfg.DecodeStages + 2, HypCfg.RenameStages + 1,
               HypCfg.AluStages + 2, 3),
      HypCfg.DcacheHitExtra + 3, HypCfg.CsrReadStages + 1, 1);
  localparam int unsigned DRAIN_W = (DRAIN_CYCLES > 1) ? $clog2(DRAIN_CYCLES) : 1;

  // comb outputs of flush_ctrl (the reference's direct outputs)
  logic set_pc_comb, flush_if_comb, flush_unissued_comb, flush_id_comb;
  logic flush_ex_comb, flush_bp_comb, flush_icache_comb, flush_dcache_comb;
  logic flush_tlb_comb, flush_tlb_vvma_comb, flush_tlb_gvma_comb;
  logic mem_replay_comb;
  // leg classes: refetch flushes assert set_pc_comb; the drain_force kill is
  // a kill-only full flush; exceptions/eret/debug are the immediate class.
  logic refetch_flush, kill_only_flush, exc_flush;

  logic [DRAIN_W-1:0]      drain_cnt_q;
  logic [G6LCCfg.VLEN-1:0] drain_pc_q;
  logic                    drain_replay_q;
  logic                    drain_setpc_q;
  // captured kill mask (order matches DRAIN_PACK below)
  localparam int unsigned DMSK_W = 10;
  logic [DMSK_W-1:0]       drain_mask_q;
  logic [DMSK_W-1:0]       comb_mask;

  assign comb_mask = {flush_unissued_comb, flush_id_comb, flush_ex_comb,
                      flush_bp_comb, flush_icache_comb, flush_dcache_comb,
                      flush_tlb_comb, flush_tlb_vvma_comb, flush_tlb_gvma_comb,
                      flush_if_comb};

  assign refetch_flush  = set_pc_comb & flush_ex_comb;
  assign kill_only_flush= drain_force_i;
  assign exc_flush      = ex_valid_i | eret_i |
                          (G6LCCfg.DebugEn & set_debug_pc_i);
  assign drain_pending_o = (drain_cnt_q != '0) |
                           (refetch_flush & (DRAIN_CYCLES > 1));
  assign pc_commit_hold_o = drain_pc_q;

assign commit_flush = ex_valid_i | eret_i
      | (G6LCCfg.DebugEn & set_debug_pc_i)
      | flush_csr_i | flush_acc_i | drain_force_i
      | ((G6LCCfg.RVA | G6LCCfg.OoOEn) & flush_commit_i)
      | fence_i | fence_i_i
      | (G6LCCfg.RVS & sfence_vma_i)
      | (G6LCCfg.RVH & (hfence_vvma_i | hfence_gvma_i));

  // ------------
  // Flush CTRL
  // ------------
  always_comb begin : flush_ctrl
    fence_active_d         = fence_active_q;
    fence_i_active_d       = fence_i_active_q;
    set_pc_comb            = 1'b0;
    flush_if_comb          = 1'b0;
    flush_unissued_comb    = 1'b0;
    flush_id_comb          = 1'b0;
    flush_ex_comb          = 1'b0;
    flush_dcache_comb      = 1'b0;
    flush_icache_comb      = 1'b0;
    flush_tlb_comb         = 1'b0;
    flush_tlb_vvma_comb    = 1'b0;
    flush_tlb_gvma_comb    = 1'b0;
    flush_bp_comb          = 1'b0;
    mem_replay_comb        = 1'b0;
    // ------------
    // Mis-predict
    // ------------
    // Only real EX is_mispredict. Matching taken Jump must not flush_if:
    // without NPC reseed it discards the correct target stream (early
    // load-misalign/illegal); with reseed via is_mispredict, TAGE RAS restore
    // -> IAF mepc=0x1400000000; reseed without TAGE double-pushes RAS -> PC=0x4.
    // Hang-6 residual fallthrough needs a selective IQ kill (not global flush).
    // Note (R3a): do NOT flush_ex here -- that would drop older still-speculative
    // correct-path stores from the STQ. Younger-cancel must not mark STORE
    // cancelled (scoreboard); STQ flush remains full-flush only (fence/exception).
    // Note (R28): gate on .valid. A stale resolve of an already-cancelled
    // branch (dropped by an older mispredict) still carries is_mispredict=1;
    // flushing IF without a redirect record makes the FTQ flush+push reseed
    // npc_q (already stepped to next_block) and drops the real target.
`ifdef G6LC_MUT_CTRL_STALE_RESOLVE
    // Review-only mutation: the .valid gate is dropped -- a stale resolve
    // flushes IF/unissued and the FTQ reseeds npc over the redirect target.
    if (resolved_branch_i.is_mispredict) begin
`else
    if (resolved_branch_i.valid && resolved_branch_i.is_mispredict) begin
`endif
      // flush only un-issued instructions
      flush_unissued_comb    = 1'b1;
      // and if stage
      flush_if_comb          = 1'b1;
    end
    // EXTRACT E3: I4x/bz/ce predicted-correct Jump/Return/JumpR IQ kill.
    // B already ends the packet at the first predicted CF (`packet_upto_cf`)
    // and kills in-flight on `bp_fire`. A keeps the extra unissued flush.
`ifndef G6LC_FETCH_B
    if (g6lc_cf_unissued::flush(
            G6LCCfg,
            resolved_branch_i.valid,
            resolved_branch_i.is_mispredict,
            resolved_branch_i.is_taken,
            resolved_branch_i.cf_type)) begin
      flush_unissued_comb    = 1'b1;
    end
`endif

    // ---------------------------------
    // FENCE
    // ---------------------------------
    if (fence_i) begin
      // this can be seen as a CSR instruction with side-effect
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;
      // this is not needed in the case since we
      // have a write-through cache in this case
      // or we are expecting explicit flush/inval via RVZiCbom
      if (G6LCCfg.DcacheFlushOnFence) begin
        flush_dcache_comb    = 1'b1;
        fence_active_d       = 1'b1;
      end
    end

    // ---------------------------------
    // FENCE.I
    // ---------------------------------
    if (fence_i_i) begin
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;
      flush_icache_comb      = 1'b1;
      // this is not needed in the case since we
      // have a write-through cache in this case
      // When handling fence.i, flush both caches and activate fence_i state
      if (G6LCCfg.DcacheFlushOnFenceI) begin
        flush_dcache_comb    = 1'b1;
        fence_active_d       = 1'b1;
        fence_i_active_d     = 1'b1;
      end
    end

    // this is not needed in the case since we
    // have a write-through cache in this case
    if (G6LCCfg.DcacheFlushOnFence || G6LCCfg.DcacheFlushOnFenceI) begin
      // Wait for the acknowledge here
      // Deassert fence_i state only after DCache flush completes
      if (flush_dcache_ack_i && fence_i_active_q) begin
        fence_i_active_d = 1'b0;
      end
      if (flush_dcache_ack_i && fence_active_q) begin
        fence_active_d = 1'b0;
        // keep the flush dcache signal high as long as we didn't get the acknowledge from the cache
      end else if (fence_active_q) begin
        flush_dcache_comb = 1'b1;
      end
    end
    // ---------------------------------
    // SFENCE.VMA
    // ---------------------------------
    if (G6LCCfg.RVS && sfence_vma_i) begin
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;

      if (G6LCCfg.RVH && v_i) flush_tlb_vvma_comb = 1'b1;
      else flush_tlb_comb = 1'b1;
    end

    // ---------------------------------
    // HFENCE.VVMA
    // ---------------------------------
    if (G6LCCfg.RVH && hfence_vvma_i) begin
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;

      flush_tlb_vvma_comb    = 1'b1;
    end

    // ---------------------------------
    // HFENCE.GVMA
    // ---------------------------------
    if (G6LCCfg.RVH && hfence_gvma_i) begin
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;

      flush_tlb_gvma_comb    = 1'b1;
    end

    // ---------------------------------
    // CSR side effects and accelerate port
    // ---------------------------------
    // Set PC to commit stage and flush pipeline
    if (flush_csr_i || flush_acc_i) begin
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;
    end else if ((G6LCCfg.RVA || G6LCCfg.OoOEn) && flush_commit_i) begin
      set_pc_comb            = 1'b1;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;
      mem_replay_comb        = replay_i;
    end

    // ---------------------------------
    // 1. Exception
    // 2. Return from exception
    // ---------------------------------
    if (ex_valid_i || eret_i || (G6LCCfg.DebugEn && set_debug_pc_i)) begin
      // don't flush pcgen as we want to take the exception: Flush PCGen is not a flush signal
      // for the PC Gen stage but instead tells it to take the PC we gave it
      set_pc_comb            = 1'b0;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;
      // this potentially reduces performance, but is needed
      // to suppress speculative fetches to virtual memory from
      // machine mode. TODO: remove when PMA checkers have been
      // added to the system
      flush_bp_comb          = 1'b1;
    end

    // ---------------------------------
    // U6.1 fine-grain SMT switch
    // ---------------------------------
    // Flush frontend IF path and drop unissued decode; do NOT assert flush_id
    // (that clears the scoreboard) or flush_ex so in-flight ops of the outgoing
    // hart can drain. CSR/RF bank by instruction hart_id. Do NOT flush BP --
    // RAS/GHR are per-hart and must survive. PC from g6lc_smt_pc_bank.
    // The override is skipped when a commit-level flush coincides with the
    // switch under mixed residency -- its full-flush outputs above then stand.
    if (G6LCCfg.NrHarts > 1 && smt_switch_i
        && !(MixedSmt && commit_flush && !SwitchGuardMut)) begin
      set_pc_comb            = 1'b0;
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b0;
      flush_ex_comb          = 1'b0;
      flush_bp_comb          = 1'b0;
    end

    // ---------------------------------
    // N1c bounded drain force
    // ---------------------------------
    // Kill the resident hart's uncommitted state exactly like a commit-level
    // flush but WITHOUT set_pc_commit_o: the outgoing hart's restart PC is
    // banked by g6lc_smt_pc_bank through npc_alt at the switch. Under the
    // drained handoff every in-flight entry belongs to the resident hart, so
    // the global kill is hart-scoped. The selector asserts this only when no
    // uncancellable side effect is in flight, so it cannot race a commit
    // redirect. Ordered last so the kill can never be degraded by the switch
    // override; drained handoff only, constant-0 otherwise.
    if (drain_force_i) begin
      flush_if_comb          = 1'b1;
      flush_unissued_comb    = 1'b1;
      flush_id_comb          = 1'b1;
      flush_ex_comb          = 1'b1;
    end
  end

  // ----------------------
  // hyp8 counted drain output stage (H1)
  // ----------------------
  // The comb legs above are classified and either pass through immediately
  // (partials, exception class, trivial DRAIN_CYCLES==1 config) or arm the
  // drain counter: kill outputs are held for DRAIN_CYCLES cycles and the
  // refetch (set_pc_commit_o + the captured pc/replay tag) is raised on the
  // last cycle. An exception-class event releases the drain early -- the
  // reference's last-write-wins ordering let the exception leg overwrite
  // every other flush output; its pending cache/TLB kills are OR'd in so a
  // mid-drain sfence's TLB kill is not truncated.
  // Narrow drain class, outside the output bundle. 0 exc, 1 arm,
  // 2 body, 3 pass-through. hyp8 drain length is greater than 1.
  logic [1:0] drain_sel;
  logic       drain_last;
  always_comb begin
    if (exc_flush) drain_sel = 2'd0;
    else if (refetch_flush || kill_only_flush) drain_sel = 2'd1;
    else if (drain_cnt_q != '0) drain_sel = 2'd2;
    else drain_sel = 2'd3;
  end
  assign drain_last = (drain_cnt_q == {{DRAIN_W - 1{1'b0}}, 1'b1});

  always_comb begin : drain_out
    // defaults: pass-through of the comb legs
    set_pc_commit_o        = set_pc_comb;
    flush_if_o             = flush_if_comb;
    flush_unissued_instr_o = flush_unissued_comb;
    flush_id_o             = flush_id_comb;
    flush_ex_o             = flush_ex_comb;
    flush_bp_o             = flush_bp_comb;
    flush_icache_o         = flush_icache_comb;
    flush_dcache           = flush_dcache_comb;
    flush_tlb_o            = flush_tlb_comb;
    flush_tlb_vvma_o       = flush_tlb_vvma_comb;
    flush_tlb_gvma_o       = flush_tlb_gvma_comb;
    mem_replay_pc_o        = mem_replay_comb;

    if (DRAIN_CYCLES > 1) begin
      unique case (drain_sel)
        2'd0: begin
          // immediate class: the live trap redirect must not land in held
          // kill stages. Release the drain; keep its cache/TLB kills pending.
          flush_tlb_o      |= drain_mask_q[3];
          flush_tlb_vvma_o |= drain_mask_q[2];
          flush_tlb_gvma_o |= drain_mask_q[1];
          flush_dcache     |= drain_mask_q[4];
        end
        2'd1: begin
          // drain trigger cycle: assert the kill set but withhold the refetch
          set_pc_commit_o = 1'b0;
          mem_replay_pc_o = 1'b0;
        end
        2'd2: begin
          // drain body: replay the captured kill mask; last cycle re-raises
          // the refetch with the captured pc/replay tag
          flush_unissued_instr_o = drain_mask_q[9];
          flush_id_o             = drain_mask_q[8];
          flush_ex_o             = drain_mask_q[7];
          flush_bp_o             = drain_mask_q[6];
          flush_icache_o         = drain_mask_q[5];
          flush_dcache           = drain_mask_q[4];
          flush_tlb_o            = drain_mask_q[3];
          flush_tlb_vvma_o       = drain_mask_q[2];
          flush_tlb_gvma_o       = drain_mask_q[1];
          flush_if_o             = drain_mask_q[0];
          if (drain_last) begin
            set_pc_commit_o = drain_setpc_q;
            mem_replay_pc_o = drain_replay_q;
          end
        end
        default: ;
      endcase
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin : drain_seq
    if (!rst_ni) begin
      drain_cnt_q    <= '0;
      drain_pc_q     <= '0;
      drain_replay_q <= 1'b0;
      drain_setpc_q  <= 1'b0;
      drain_mask_q   <= '0;
    end else begin
      if (DRAIN_CYCLES > 1) begin
        if (exc_flush) begin
          drain_cnt_q   <= '0;
          drain_mask_q  <= '0;
          drain_setpc_q <= 1'b0;
        end else if (refetch_flush || kill_only_flush) begin
          drain_cnt_q    <= DRAIN_CYCLES - 1;
          drain_pc_q     <= pc_commit_i;
          drain_replay_q <= mem_replay_comb;
          // the refetch qualifier is latched separately from the kill
          // mask: drain_force also raises flush_unissued, so a mask bit
          // cannot tell a refetch drain from a kill-only one. A refetch
          // leg coincident with drain_force ORs in.
          drain_setpc_q  <= refetch_flush | drain_setpc_q;
          drain_mask_q   <= comb_mask | drain_mask_q;
        end else if (drain_cnt_q != '0) begin
          drain_cnt_q  <= drain_cnt_q - 1'b1;
          drain_mask_q <= drain_mask_q;
          drain_pc_q   <= drain_pc_q;
        end else begin
          drain_setpc_q <= 1'b0;
        end
      end
    end
  end

  // ----------------------
  // Halt Logic
  // ----------------------
  always_comb begin
    // halt the core if the fence is active
    halt_o = halt_csr_i || halt_acc_i || ((G6LCCfg.DcacheFlushOnFence || G6LCCfg.DcacheFlushOnFenceI) && fence_active_q);
    // Halt frontend during fence.i to synchronize ICache/DCache flushes
    halt_frontend_o = fence_i_active_q;
  end

  // ----------------------
  // Registers
  // ----------------------
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (~rst_ni) begin
      fence_active_q   <= 1'b0;
      fence_i_active_q <= 1'b0;
      flush_dcache_o   <= 1'b0;
    end else begin
      fence_active_q   <= fence_active_d;
      fence_i_active_q <= fence_i_active_d;
      // register on the flush signal, this signal might be critical
      flush_dcache_o   <= flush_dcache;
    end
  end
endmodule
